      document.getElementById("out").textContent = '결과: ' + String((parseFloat(document.getElementById("a").value) || 0) + (parseFloat(document.getElementById("b").value) || 0));
    });
    document.getElementById("sub").addEventListener('click', function () {
      document.getElementById("out").textContent = '결과: ' + String((parseFloat(document.getElementById("a").value) || 0) - (parseFloat(document.getElementById("b").value) || 0));
